def solve():
    import sys
    input = sys.stdin.read().split()
    data = list(map(int, input))

    if not data:
        return

    idx = 0
    n = data[idx]; idx += 1
    m = data[idx]; idx += 1
    k = data[idx]; idx += 1
    s = data[idx]; idx += 1

    # Read n rows of m notes each
    a = []
    for i in range(n):
        row = data[idx:idx+m]
        idx += m
        a.append(row)

    # Read the song
    q = data[idx:idx+s]
    idx += s

    # dp[i][s][f] = maximum complexity after i notes, ending at string s and fret f
    # We'll use a list of dictionaries for efficiency
    prev = {i: {} for i in range(n)}
    for i in range(n):
        for f in range(m):
            if a[i][f] == q[0]:
                prev[0][(i, f)] = 0  # Starting at this position with complexity 0

    for i in range(1, s):
        curr = {}
        curr_idx = 0
        for s1 in range(n):
            for f1 in range(m):
                if a[s1][f1] == q[i]:
                    # Try all previous positions
                    for s0 in range(n):
                        for f0 in range(m):
                            if a[s0][f0] == q[i-1]:
                                # Calculate complexity
                                move_complexity = abs(s1 - s0) + abs(f1 - f0)
                                prev_complexity = prev[i-1].get((s0, f0), -1)
                                curr_complexity = max(prev_complexity, move_complexity) if prev_complexity != -1 else move_complexity

                                curr[(s1, f1)] = max(curr.get((s1, f1), -1), curr_complexity)
        prev[i] = curr

    # Find the maximum complexity
    max_complexity = max(prev[s-1].values())
    print(max_complexity)

solve()
