import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # If all elements are non-positive, answer is 0
    all_non_positive = all(x <= 0 for x in a)
    if all_non_positive:
        print(0)
        return

    max_score = 0

    # Consider all possible segments [l, r]
    for l in range(n):
        for r in range(l, n):
            segment_sum = sum(a[l:r+1])
            segment_max = max(a[l:r+1])
            score = segment_sum - segment_max
            if score > max_score:
                max_score = score

    print(max_score)

if __name__ == "__main__":
    solve()
