# Read input
import sys

def solve():
    a, b = map(int, sys.stdin.readline().split())

    # Base case: already have 1 resistor
    count = 1

    # Work backwards more efficiently
    while a != 1 or b != 1:
        if a > b:
            if a % b == 0:
                # a = n*b, add n resistors in series
                count += a // b - 1  # Subtract 1 because we already counted the first one
                a = 1
            else:
                # a/b = (a//b + 1) + (a%b)/b
                # So we need to add (a//b) resistors in series
                count += a // b
                a = a % b
        else:
            if b % a == 0:
                # b = n*a, add n resistors in parallel
                count += b // a - 1
                b = 1
            else:
                # a/b = a/(b//a) + (b%a)/a
                # So we need to add (b//a) resistors in parallel
                count += b // a
                b = b % a

    return count

if __name__ == "__main__":
    print(solve())
"}

