def count_camels(n, t):
    """Count the number of valid camels with n vertices and t humps."""

    # Backtracking to count valid sequences
    def backtrack(pos, prev_y, humps, valleys, seq):
        """Recursive backtracking function."""
        if pos == n:
            # Check if we have exactly t humps and t-1 valleys
            if humps == t and valleys == t - 1:
                return 1
            return 0

        total = 0
        for curr_y in range(1, 5):
            if curr_y != prev_y:
                # Check if this position creates a hump or valley
                if pos > 1 and pos < n:
                    prev_prev_y = seq[pos-2]
                    next_y = seq[pos] if pos+1 < n else None

                    # Check if we have a hump (local maximum)
                    if prev_prev_y < curr_y and curr_y > next_y:
                        total += backtrack(pos + 1, curr_y, humps + 1, valleys, seq + [curr_y])

                    # Check if we have a valley (local minimum)
                    elif prev_prev_y > curr_y and curr_y < next_y:
                        total += backtrack(pos + 1, curr_y, humps, valleys + 1, seq + [curr_y])

                    # If neither, just continue
                else:
                    total += backtrack(pos + 1, curr_y, humps, valleys, seq + [curr_y])

        return total

    return backtrack(1, 0, 0, 0, [])

def main():
    n, t = map(int, input().split())
    print(count_camels(n, t))

if __name__ == "__main__":
