import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    probabilities = list(map(float, data[1:n+1]))

    max_prob = 0.0

    # Try all subsets of friends
    for mask in range(1, 1 << n):
        # Count number of friends in this subset
        k = bin(mask).count('1')

        # Probability of exactly one success in this subset
        if k == 0:
            continue
        if k == 1:
            # Exactly one friend, probability = p_i
            prob = probabilities[bin(mask).index('1')]
        else:
            # Exactly one success in k friends
            prob = 0.0
            for i in range(n):
                if (mask >> i) & 1:
                    p = probabilities[i]
                    term = p * (1 - p) ** (k - 1)
                    prob += term

        max_prob = max(max_prob, prob)

    print(f"{max_prob:.12f}")

if __name__ == "__main__":
    solve()
