    for i in range(n):
        for j in range(i, n):
            # Check if this substring contains at least one palindrome of length > 1
            contains_palindrome = False
            for k in range(i, j + 1):
                # Check palindrome centered at k with radius 1
                if k > 0 and k < j and s[k-1] == s[k+1]:
                    contains_palindrome = True
                    break
                elif k > 0 and s[k-1] == s[k]:
                    contains_palindrome = True
                    break
                elif k < j and s[k] == s[k+1]:
                    contains_palindrome = True
                    break

            if contains_palindrome:
                count += 1

    return count

