    # Check if every character in s[i..j] is part of at least one palindrome
    for k in range(i, j + 1):
        # Check if s[k] is part of a palindrome
        if k > 0 and k < j and s[k-1] == s[k+1]:
            continue  # s[k] is part of a palindrome of length 3
        elif k > 0 and s[k-1] == s[k]:
            continue  # s[k] is part of a palindrome of length 2
        elif k < j and s[k] == s[k+1]:
            continue  # s[k] is part of a palindrome of length 2
        else:
            return False

    return True

