    b = [int(next(it)) for _ in range(m)]

    # Compute prefix GCDs for the original array
    prefix_gcds = compute_prefix_gcds(a)

    # Compute set of good primes
    good_primes = set()
    primes = set()
    for p in range(2, 100000):  # We'll check primes up to 100000
        if is_prime(p):
            primes.add(p)
    for p in primes:
        if p not in b:
            good_primes.add(p)

    # Memoize beauty for each prefix GCD
    prefix_beauties = {}
    for g in prefix_gcds:
        prefix_beauties[g] = beauty(g, good_primes)

    # Now we need to decide which operations to apply
    # Let's use dynamic programming where we track the state after processing i elements
    # dp[i] = maximum beauty we can achieve after processing elements 1..i
    # We'll consider two cases: we either apply an operation at i or not

    dp = [-1] * (n + 1)
    dp[0] = 0  # Beauty of empty array is 0

    for i in range(1, n + 1):
        # Option 1: Don't apply operation at i
        # The first i-1 elements have some value v (from previous operations)
        # The beauty of the first i-1 elements is dp[i-1]
        # The i-th element remains a[i-1]
        if dp[i-1] != -1:
            # After processing i-1 elements, all elements 1..i-1 are equal to v
            # The beauty of elements 1..i-1 is beauty(v, good_primes) * (i-1) = dp[i-1]
            # The beauty of the i-th element is beauty(a[i-1], good_primes)
            dp[i] = dp[i-1] + beauty(a[i-1], good_primes)

        # Option 2: Apply operation at i
        # After applying at i, all elements 1..i become the GCD of the first i elements
        # The GCD of elements 1..i (after previous operations) is prefix_gcds[i-1]
        if i <= len(prefix_gcds):
            current_gcd = prefix_gcds[i-1]
            beauty_i = beauty(current_gcd, good_primes)
            # The beauty of elements 1..i is beauty_i * i
            # But we need to be careful: we already have dp[i-1] for elements 1..i-1
            # After applying at i, all elements 1..i are equal to current_gcd
            # So we need to replace the beauty of elements 1..i-1 with beauty_i * (i-1)
            # And then add the beauty of element i (which is already current_gcd)
            dp[i] = max(dp[i], beauty_i * (i - 1) + beauty_i)

    print(dp[n])

if __name__ == "__main__":
    solve()

