import sys

def can_place_bottles(bottles, h):
    """Check if we can place the given bottles in the fridge."""
    bottles = sorted(bottles, reverse=True)  # Sort tallest first
    column1 = 0  # space above shelf in column 1
    column2 = 0  # space above shelf in column 2

    for height in bottles:
        if height <= column1:
            column1 -= height
        elif height <= column2:
            column2 -= height
        else:
            return False
    return True

