    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    h = int(data[1])
    bottles = list(map(int, data[2:2+n]))

    # Binary search on k
    low = 1
    high = n
    answer = 1

    while low <= high:
        mid = (low + high) // 2
        if can_place_bottles(bottles[:mid], h):
            answer = mid
            low = mid + 1
        else:
            high = mid - 1

    print(answer)

