def rotate_90(grid, X, Y):
    """Rotate a grid 90 degrees clockwise"""
    return [[grid[X - 1 - y][x] for y in range(Y)] for x in range(X)]

def rotate_180(grid, X, Y):
    """Rotate a grid 180 degrees"""
    return [[grid[X - 1 - y][Y - 1 - x] for y in range(Y)] for x in range(X)]

def rotate_270(grid, X, Y):
    """Rotate a grid 270 degrees clockwise (or 90 counter-clockwise)"""
    return [[grid[y][Y - 1 - x] for y in range(Y)] for x in range(X)]

def get_all_rotations(grid, X, Y):
    """Get all 4 rotations of a grid"""
    return [grid, rotate_90(grid, X, Y), rotate_180(grid, X, Y), rotate_270(grid, X, Y)]

def is_good_puzzle(grid, A, B, X, Y):
    """Check if a puzzle with given piece size is good"""
    # Extract all pieces
    pieces = []
    for i in range(0, A, X):
        for j in range(0, B, Y):
            # Extract the piece
            piece = []
            for x in range(X):
                row = []
                for y in range(Y):
                    row.append(grid[i + x][j + y])
                piece.append(row)
            pieces.append(piece)

    # Check for duplicates
    for i in range(len(pieces)):
        for j in range(i + 1, len(pieces)):
            # Check if any rotation of piece i matches piece j
            matches = False
            for rot in get_all_rotations(pieces[i], X, Y):
                if rot == pieces[j]:
                    matches = True
                    break
            if matches:
                return False
    return True

def solve():
    A, B = map(int, input().split())
    grid = [list(input().strip()) for _ in range(A)]

    # Find all divisors
    divisors_A = [i for i in range(1, A + 1) if A % i == 0]
    divisors_B = [j for j in range(1, B + 1) if B % j == 0]

    count = 0
    min_area = float('inf')
    min_X = float('inf')

    for X in divisors_A:
        for Y in divisors_B:
            if is_good_puzzle(grid, A, B, X, Y):
                count += 1
                area = X * Y
                if area < min_area or (area == min_area and X < min_X):
                    min_area = area
                    min_X = X

    print(count)
    print(min_X, min_area)

solve()
