from collections import defaultdict, deque

def has_even_edges(m):
    return m % 2 == 0

# Build adjacency list for edges (edge indices)
def build_edge_adjacency_list(n, m, edges):
    adj = defaultdict(list)
    for i, (u, v) in enumerate(edges):
        adj[u].append(i)
        adj[v].append(i)
    return adj

# Find augmenting path from start
def bfs(start, adj, match, visited, parent):
    queue = deque([start])
    visited.add(start)
    parent[start] = -1

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                parent[v] = u
                queue.append(v)
                if match[v] == -1:
                    # Found an augmenting path
                    return True, parent
    return False, parent

# Augment the matching
def augment(start, end, parent, match):
    path = []
    node = end
    while node != start:
        path.append(node)
        node = parent[node]
    path.append(start)

    for i in range(len(path) - 1, -1, -2):
        v = path[i]
        u = path[i - 1] if i > 0 else start
        match[v] = u

# Find perfect matching
def find_perfect_matching(n, m, edges):
    adj = build_edge_adjacency_list(n, m, edges)
    match = [-1] * m

    for u in range(n):
        visited = set()
        parent = {}
        found, parent = bfs(u, adj, match, visited, parent)
        if found:
            augment(u, end, parent, match)

    if sum(1 for i in range(m) if match[i] != -1) == m:
        return match
    else:
        return None


def solve():
    n, m = map(int, input().split())
    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append((u, v))

    if not has_even_edges(m):
        print("No solution")
        return

    match = find_perfect_matching(n, m, edges)
    if match is None:
        print("No solution")
        return

    # Build paths
    paths = []
    for i in range(m):
        if match[i] == -1:
            continue  # This shouldn't happen if we have perfect matching
        j = match[i]
        # Find the common vertex between edge i and edge j
        u1, v1 = edges[i]
        u2, v2 = edges[j]

        if u1 == u2 or u1 == v2:
            common = u1
        elif v1 == u2 or v1 == v2:
            common = v1
        else:
            # Shouldn't happen with perfect matching
            return

        # Build the path
