import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Read edges
    edges = []
    adj = [[] for _ in range(n + 1)]  # 1-indexed

    for edge_id in range(m):
        u = int(next(it))
        v = int(next(it))
        edges.append((u, v))
        adj[u].append((u, v, edge_id))
        adj[v].append((v, u, edge_id))

    # Build adjacency lists for vertices
    vertex_edges = [[] for _ in range(n + 1)]  # vertex_edges[i] = list of edges incident to i

    for i in range(n + 1):
        for u, v, edge_id in adj[i]:
            vertex_edges[i].append(edge_id)

    # If number of edges is odd, impossible
    if m % 2 != 0:
        print("No solution")
        return

    # Build edge adjacency graph
    edge_adj = [[] for _ in range(m)]
    for i in range(n + 1):
        for j in range(len(vertex_edges[i]) - 1):
            for k in range(j + 1, len(vertex_edges[i])):
                # Edge j and edge k share vertex i
                edge_adj[vertex_edges[i][j]].append(vertex_edges[i][k])

    # Find matching in edge_adj
    used = [False] * m
    result = []

    for i in range(m):
        if not used[i] and len(edge_adj[i]) > 0:
            # Find an adjacent edge
            j = edge_adj[i][0]
            if not used[j]:
                # Pair them
                result.append((edges[i][0], edges[i][1], edges[j][0]))
                result.append((edges[j][0], edges[j][1], edges[i][1]))
                used[i] = True
                used[j] = True

    # Check if all edges are used
    if sum(used) != m:
        print("No solution")
    else:
        for path in result:
            print(f"{path[0]} {path[1]} {path[2]}")

if __name__ == "__main__":
    solve()
