    import sys
    import math
    input = sys.stdin.read().split()
    data = list(map(int, input))
    it = iter(data)

    t = next(it)

    for _ in range(t):
        n = next(it)
        a = [next(it) for _ in range(n)]

        q = next(it)
        queries = [next(it) for _ in range(q)]

        # Function to check if two numbers are adjacent
        def is_adjacent(x, y):
            g = math.gcd(x, y)
            lcm = x * y // g
            val = lcm // g
            return math.isqrt(val) * math.isqrt(val) == val

        # Function to compute beauty from array
        def beauty(arr):
            # Build adjacency matrix
            adj = [[0] * n for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    if is_adjacent(arr[i], arr[j]):
                        adj[i][j] = 1
            # Count degrees
            max_deg = 0
            for i in range(n):
                deg = sum(adj[i])
                max_deg = max(max_deg, deg)
            return max_deg

        # Find max degree for each query
        results = []

        for w in queries:
            # Compute array after w transformations
            arr = a.copy()
            if w > 0:
                for _ in range(w):
                    new_arr = [1] * n
                    for i in range(n):
                        for j in range(n):
                            if is_adjacent(arr[i], arr[j]):
                                new_arr[i] *= arr[j]
                    arr = new_arr
            results.append(beauty(arr))

        sys.stdout.write("\n".join(map(str, results)))

if __name__ == "__main__":
    solve()

