                if grid[i][j] == 'A':
                    q.append((i, j))
                    visited[i][j] = True

        # Directions: (di, dj)
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # NORTH, SOUTH, WEST, EAST

