def solve():
    n, w, h = map(int, input().split())
    vertical = []  # (x, t)
    horizontal = []  # (y, t)

    for _ in range(n):
        gi, pi, ti = map(int, input().split())
        if gi == 1:
            # Vertical dancer at (pi, 0) with wait time ti
            vertical.append((pi, ti))
        else:
            # Horizontal dancer at (0, pi) with wait time ti
            horizontal.append((pi, ti))

    result = []

    # Create a list of dancers with their original order
    dancers = []
    for i in range(n):
        gi, pi, ti = map(int, input().split())
        if gi == 1:
            dancers.append((pi, ti, 'vertical'))
        else:
            dancers.append((pi, ti, 'horizontal'))

    # Process each dancer
    for x, t, typ in dancers:
        if typ == 'vertical':
            found_collision = False
            for y, t_h, typ_h in dancers:
                if typ_h == 'horizontal' and y == x and t + h == t_h + w:
                    # Collision at (x, h) at time t + h
                    time_moved = t + h - t
                    remaining_time = w - x
                    result.append((x + remaining_time, h))  # Vertical dancer goes right

                    # Horizontal dancer goes up
                    remaining_time = h - 0
                    result.append((w, y + remaining_time))  # Horizontal dancer goes up

                    # Mark both as processed
                    found_collision = True
                    break
            if not found_collision:
                result.append((x, h))
        else:
            # Horizontal dancer goes right
            result.append((w, y))

    for x, y in result:
        print(x, y)

