            count = 0
            for k in range(len_p):
                if p[k:k+len(substr)] == substr:
                    count += 1
            occurrences[substr] = count

    # Store only substrings that comply with this rule
    compliant = []
    for substr, count in occurrences.items():
        if l <= count <= r:
            compliant.append(substr)
    rule_substrings.append(compliant)

# Now count good substrings of s
good_substrings = set()

for i in range(len(s)):
    for j in range(i + 1, len(s) + 1):
        substr = s[i:j]
        is_good = True
        for compliant in rule_substrings:
            if substr not in compliant:
                is_good = False
                break
        if is_good:
            good_substrings.add(substr)

print(len(good_substrings))
