# Count parentheses
open_count = s.count('(')
close_count = s.count(')')

# Check if total is even
if (open_count + close_count) % 2 != 0:
    print(0)
    print(1, 1)
    exit()

# Check if we can make it correct by swapping two characters
# We need to balance the parentheses
def can_be_corrected(s):
    open_list = []
    close_list = []
    for i, char in enumerate(s):
        if char == '(':
            open_list.append(i)
        else:
            close_list.append(i)

    # If total is already correct
    if len(open_list) == len(close_list):
        return True, [0, 0]  # already correct

    # We need to swap a '(' and ')' to balance
    # For a correct sequence, at each position, open_count >= close_count
    # Find where it fails
    balance = 0
    failure_index = -1
    for i in range(len(s)):
        if s[i] == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            failure_index = i
            break

    # If we pass through without failing, need to check end
    if failure_index == -1:
        return False, [0, 0]  # should be correct but not fully balanced

    # At failure_index, we have ')' at position failure_index
    # We need to swap this with a '(' to its left
    # Find the closest '(' to the left that we can swap
    for i in range(failure_index):
        if s[i] == '(':
            # Swap i and failure_index
            return True, [i + 1, failure_index + 1]

    # No swap possible
    return False, [0, 0]

is_correct, indices = can_be_corrected(s)

if is_correct:
    print(n)
    print(indices[0], indices[1])
else:
    # Check all swaps for maximum beauty
    max_beauty = 0
    best_l, best_r = 1, 1

    for l in range(n):
        for r in range(n):
            s_list = list(s)
            s_list[l], s_list[r] = s_list[r], s_list[l]

            beauty = 0
            balance = 0
            is_correct = True
            for char in s_list:
                if char == '(':
                    balance += 1
                else:
                    balance -= 1
                if balance < 0:
                    is_correct = False
                    break
            if is_correct and balance == 0:
                beauty = n

            if beauty > max_beauty:
                max_beauty = beauty
                best_l, best_r = l + 1, r + 1


