def rotate(piece, rotations=1):
    """Rotate the piece by 90 degrees 'rotations' times."""
    # Convert to list of lists
    piece_list = [list(row) for row in piece]

    if rotations == 1:
        # 90 degree rotation: transpose and reverse each row
        rotated = list(zip(*piece_list[::-1]))
        return [''.join(row) for row in rotated]
    elif rotations == 2:
        # 180 degree rotation: reverse both row and column
        rotated = piece_list[::-1][::-1]
        return [''.join(row) for row in rotated]
    elif rotations == 3:
        # 270 degree rotation: transpose and reverse each column
        rotated = list(zip(*piece_list))[::-1]
        return [''.join(row) for row in rotated]
    return piece

def get_all_rotations(piece):
    """Get all 4 rotations of the piece."""
    return [rotate(piece, i) for i in range(4)]

def get_piece(grid, X, Y, i, j):
    """Get the piece at position (i,j) with size X×Y."""
    piece = []
    for x in range(X):
        row = []
        for y in range(Y):
            row.append(grid[i*X + x][j*Y + y])
        piece.append(''.join(row))
    return piece

def is_good_puzzle(A, B, grid, X, Y):
    """Check if the puzzle with piece size X×Y is good."""
    pieces = []
    # Get all pieces and their rotations
    for i in range(A // X):
        for j in range(B // Y):
            piece = get_piece(grid, X, Y, i, j)
            rotations = get_all_rotations(piece)
            pieces.extend(rotations)

    # Convert to tuples and check for duplicates
    pieces_set = set(tuple(piece) for piece in pieces)
    return len(pieces_set) == len(pieces)

def solve():
    A, B = map(int, input().split())
    grid = [list(input().strip()) for _ in range(A)]

    good_puzzles = []
    min_area = float('inf')
    min_X = float('inf')

    # Try all possible piece sizes
    for X in range(1, A + 1):
        if A % X != 0:
            continue
        for Y in range(1, B + 1):
            if B % Y != 0:
                continue

            if is_good_puzzle(A, B, grid, X, Y):
                good_puzzles.append((X, Y))

                # Update minimum
                area = X * Y
                if area < min_area or (area == min_area and X < min_X):
                    min_area = area
                    min_X = X

    print(len(good_puzzles))
    print(min_X, min_area)

solve()
