q = int(input())
for _ in range(q):
    a, b = map(int, input().split())
    s = input().strip()

    # Check if Alice can make a move (find substring of length a with at least one '.')
    alice_can_move = False
    for i in range(len(s) - a + 1):
        if '.' in s[i:i+a]:
            alice_can_move = True
            break

    if not alice_can_move:
        print("NO")
        continue

    # For each position Alice can move, check if Bob cannot make a move afterwards
    alice_wins = False
    for i in range(len(s) - a + 1):
        # Create a new string after Alice's move
        new_s = s[:i] + 'X'*a + s[i+a:]

        # Check if Bob can make a move (find substring of length b with at least one '.')
        bob_can_move = False
        for j in range(len(new_s) - b + 1):
            if '.' in new_s[j:j+b]:
                bob_can_move = True
                break

        if not bob_can_move:
            alice_wins = True
            break

    print("YES" if alice_wins else "NO")
