import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    result = 0

    # For each bit position from 0 to 20 (since 10^7 fits in 24 bits)
    for bit in range(21):
        cnt_1 = 0  # count of numbers with this bit set
        for num in a:
            if num & (1 << bit):
                cnt_1 += 1

        cnt_0 = n - cnt_1

        # Number of pairs with different bits at this position
        pairs_with_diff = cnt_1 * cnt_0

        # If this count is odd, set the bit in the result
        if pairs_with_diff % 2 == 1:
            result |= (1 << bit)

    print(result)

if __name__ == "__main__":
    solve()
"}

