def find_min_rows(n):
    """Find the minimum number of rows matrix b can have"""
    # If n is odd, minimum rows is n
    if n % 2 == 1:
        return n

    # If n is even, we can try different powers of 2
    # The minimum number of rows is n divided by the largest power of 2 that divides it

    # Find the largest power of 2 that divides n
    power_of_two = 1
    while power_of_two <= n:
        if n % power_of_two == 0:
            power_of_two *= 2

    # Now power_of_two is twice the largest power of 2 that divides n
    # So divide by 2
    power_of_two //= 2

    return n // power_of_two

def main():
    n, m = map(int, input().split())
    print(find_min_rows(n))

if __name__ == "__main__":
    main()
"}

