def is_good(v, l):
    """Check if a substring with v vowels and length l is good"""
    return v <= 2 * (l - v)  # v <= 2c where c = l - v

def solve():
    s = input().strip()
    n = len(s)

    # Count vowels in each position
    vowels = [0] * n
    for i, char in enumerate(s):
        vowels[i] = 1 if char.lower() in {'a', 'e', 'i', 'o', 'u'} else 0

    # Prefix sum of vowels
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + vowels[i]

    max_len = 0
    count = 0

    # Try all possible substrings
    for start in range(n):
        v = 0
        for end in range(start, n):
            v += vowels[end]
            l = end - start + 1
            if is_good(v, l):
                if l > max_len:
                    max_len = l
                    count = 1
                elif l == max_len:
                    count += 1
            else:
                break  # Can't get longer substring starting at this position

    if max_len == 0:
        print("No solution")
    else:
        print(f"{max_len} {count}")

solve()
"}

