def main():
    # Read input
    n, m = map(int, input().split())

    # Build graph with only 0-weight edges
    # We'll use a set of edges that have weight 0
    edges = set()

    # Read m edges with weight 1
    for _ in range(m):
        a, b = map(int, input().split())
        edges.add((a, b))
        edges.add((b, a))  # Undirected graph

    # Find connected components using Union-Find
    parent = {}

    def find(v):
        if parent[v] != v:
            parent[v] = find(parent[v])
        return parent[v]

    def union(u, v):
        pu = find(u)
        pv = find(v)
        if pu != pv:
            parent[pu] = pv

    # Initialize parent for each vertex
    for i in range(1, n + 1):
        parent[i] = i

    # We need to find connected components in the 0-weight graph
    # So we need to consider all edges that are NOT in the 1-weight graph
    # For each pair of vertices, if their edge is not in 1-weight graph, add it
    for u in range(1, n + 1):
        for v in range(u + 1, n + 1):
            if (u, v) not in edges:
                union(u, v)

    # Count the number of connected components
    components = set()
    for i in range(1, n + 1):
        components.add(find(i))

    # Number of components
    k = len(components)

    # Answer: max(0, k - 1)
    print(max(0, k - 1))

