import sys

def can_achieve(height, a, n, m, w):
    """Check if we can achieve minimum height 'height'"""
    needs = [max(0, height - a[i]) for i in range(n)]

    # Greedy watering: water windows from left to right
    days_used = 0

    for i in range(n):
        if days_used >= m:
            break

        # If this flower needs growth, water the window starting at position i
        if needs[i] > 0:

            # Water window [i, i+1, ..., min(n-1, i+w-1)]
            # This gives 1 growth to each flower in the window

            for j in range(i, min(n, i + w)):
                needs[j] -= 1

            days_used += 1

    # After watering, check if all flowers have reached the desired height
    return all(n <= 0 for n in needs)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    w = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Binary search for the maximum possible minimum height
    low = min(a)
    high = low + m * w  # Maximum possible minimum height

    answer = low

    while low <= high:
        mid = (low + high) // 2

        if can_achieve(mid, a, n, m, w):
            answer = mid
            low = mid + 1
        else:
            high = mid - 1

    print(answer)

if __name__ == "__main__":
    solve()
