        min_changes = float('inf')
        best_pattern = None

        # For each possible pair of colors
        for c1 in range(26):
            for c2 in range(26):
                if c1 == c2:
                    continue

                # Pattern 1: c1, c2, c1, c2, ...
                pattern = [chr(ord('a') + c1) if i % 2 == 0 else chr(ord('a') + c2) for i in range(m)]
                changes = sum(1 for i in range(m) if pattern[i] != row[i])

                if changes < min_changes:
                    min_changes = changes
                    best_pattern = pattern

                # Pattern 2: c2, c1, c2, c1, ...
                pattern = [chr(ord('a') + c2) if i % 2 == 0 else chr(ord('a') + c1) for i in range(m)]
                changes = sum(1 for i in range(m) if pattern[i] != row[i])

                if changes < min_changes:
                    min_changes = changes
                    best_pattern = pattern

        return min_changes, best_pattern

    # Apply greedy approach
