import sys

def solve():
    a, b = map(int, sys.stdin.readline().split())

    # Work backwards from a/b to 1/1
    count = 0

    while a != b:
        if a > b:
            # We could have come from (a-b)/b by connecting in parallel
            a -= b
            count += 1
        else:
            # We could have come from a/(a+b) by connecting in series
            b -= a
            count += 1

    return count

if __name__ == "__main__":
    print(solve())
