# Read input
cake = []
h, w = map(int, input().split())
for _ in range(h):
    row = input().strip()
    cake.append(row)

# DP table
dp = [[0] * w for _ in range(h)]

# Base case: starting cell
dp[0][0] = 1 if cake[0][0] == '*' else 0

# Fill DP table
for i in range(h):
    for j in range(w):
        if i == 0 and j == 0:
            continue  # already handled
        elif i == 0:
            # only come from left
            dp[i][j] = dp[i][j-1] + (1 if cake[i][j] == '*' else 0)
        elif j == 0:
            # only come from above
            dp[i][j] = dp[i-1][j] + (1 if cake[i][j] == '*' else 0)
        else:
            # come from either above or left
            up = dp[i-1][j]
            left = dp[i][j-1]
            if up > left:
                dp[i][j] = up + (1 if cake[i][j] == '*' else 0)
            elif up < left:
                dp[i][j] = left + (1 if cake[i][j] == '*' else 0)
            else:
                # equal values - need to consider expected value
                dp[i][j] = (up + left) / 2 + (1 if cake[i][j] == '*' else 0)

# Output the result
print(dp[-1][-1])
"}

