# Function to check if a subarray a[start:end+1] is strictly increasing
# and if we can extend it by removing one element
# Returns: max length of increasing subarray

def find_max(start, end):
    max_len = 1
    # Check if we can extend left by removing a[start-1]
    if start > 0 and a[start-1] < a[start]:
        max_len = max(max_len, 2)

    # Check if we can extend right by removing a[end]
    if end < n-1 and a[end] < a[end+1]:
        max_len = max(max_len, 2)

    # Check if we can extend both sides by removing a[start-1] and a[end]
    if start > 0 and end < n-1 and a[start-1] < a[start] and a[end] < a[end+1]:
        max_len = max(max_len, 3)

    return max_len

# Find all increasing contiguous subarrays
start = 0
for i in range(n):
    if i == 0 or a[i] > a[i-1]:
        if i - start + 1 > 1:
            result = max(result, find_max(start, i))
    else:
        start = i

print(result)
