def solve(s):
    n = len(s)
    max_length = 0
    count = 0

    # Try all possible substrings
    for i in range(n):
        current_vowels = 0
        current_consonants = 0

        # Extend substring to the right
        for j in range(i, n):
            if s[j].lower() in 'aeiou':
                current_vowels += 1
            else:
                current_consonants += 1

            # Check if good
            if current_vowels <= 2 * current_consonants:
                # Update maximum
                if j - i + 1 > max_length:
                    max_length = j - i + 1
                    count = 1
                elif j - i + 1 == max_length:
                    count += 1
            else:
                # Not good, break early
                break

    if max_length == 0:
        return "No solution"
    return f"{max_length} {count}"

