import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    H = int(data[idx])
    W = int(data[idx+1])
    idx += 2

    grid = []
    for _ in range(H):
        grid.append(data[idx])
        idx += 1

    # Simulate the mouse's greedy strategy
    i, j = 0, 0
    berries = 0

    if grid[0][0] == '*':
        berries += 1

    # Strategy: at each step, if right has berry, go right; else if below has berry, go down; else go right
    while i < H - 1 or j < W - 1:
        has_right_berry = j + 1 < W and grid[i][j+1] == '*'
        has_below_berry = i + 1 < H and grid[i+1][j] == '*'

        if has_right_berry:
            j += 1
        elif has_below_berry:
            i += 1
        else:
            # No berries ahead, go right
            j += 1

        if grid[i][j] == '*':
            berries += 1

    print(berries)

if __name__ == "__main__":
    solve()
