    a = list(map(int, data[1:1+n]))

    # Calculate lengths of increasing subarrays from left to right
    left = [1] * n
    for i in range(1, n):
        if a[i] > a[i-1]:
            left[i] = left[i-1] + 1
        else:
            left[i] = 1

    # Calculate lengths of increasing subarrays from right to left
    right = [1] * n
    for i in range(n-2, -1, -1):
        if a[i] < a[i+1]:
            right[i] = right[i+1] + 1
        else:
            right[i] = 1

    # Find the maximum length
    max_len = max(left)

    # Check if removing one element could connect two sequences
    for i in range(n):
        # Check if we can connect the left increasing subarray ending at i-1
        # with the right increasing subarray starting at i+1
        if i > 0 and a[i] > a[i-1] and i < n-1 and a[i] < a[i+1]:
