import sys

def is_vowel(char):
    return char.lower() in {'a', 'e', 'i', 'o', 'u'}

def solve(s):
    n = len(s)
    prefix_vowels = [0] * (n + 1)

    # Build prefix sum of vowels
    for i in range(n):
        prefix_vowels[i+1] = prefix_vowels[i] + (1 if is_vowel(s[i]) else 0)

    max_len = 0
    count = 0

    # Try all starting positions
    for start in range(n):
        # Try all ending positions
        for end in range(start, n):
            v = prefix_vowels[end+1] - prefix_vowels[start]
            c = (end - start + 1) - v

            # Check if substring is good
            if v <= 2 * c:
                length = end - start + 1

                # Update max and count
                if length > max_len:
                    max_len = length
                    count = 1
                elif length == max_len:
                    count += 1

    if max_len == 0:
        return "No solution"
    else:
        return f"{max_len} {count}"

if __name__ == "__main__":
    s = sys.stdin.readline().strip()
    result = solve(s)
    print(result)
"}

