def count_occurrences(text, pattern):
    """Count the number of occurrences of pattern in text."""
    count = 0
    start = 0
    while True:
        pos = text.find(pattern, start)
        if pos == -1:
            break
        count += 1
        start = pos + 1  # Move past this occurrence
    return count

def is_good_substring(s, rules, substring):
    """Check if a substring is good according to all rules."""
    for p, l, r in rules:
        occurrences = count_occurrences(p, substring)
        if occurrences < l or occurrences > r:
            return False
    return True

def main():
    s = input().strip()
    n = int(input())
    rules = []
    for _ in range(n):
        parts = input().split()
        p = parts[0]
        l = int(parts[1])
        r = int(parts[2])
        rules.append((p, l, r))

    # Generate all distinct substrings of s
    substrings = set()
    for i in range(len(s)):
        for j in range(i, len(s)):
            substrings.add(s[i:j+1])

    # Count good substrings
    good_count = 0
    for sub in substrings:
        if is_good_substring(s, rules, sub):
            good_count += 1

    print(good_count)

if __name__ == "__main__":
    main()
