def count_occurrences(p, t):
    """Count how many times substring t appears in string p."""
    count = 0
    len_t = len(t)
    for i in range(len(p) - len_t + 1):
        if p[i:i+len_t] == t:
            count += 1
    return count

def is_good(t, rules):
    """Check if substring t complies with all rules."""
    for p, l, r in rules:
        occurrences = count_occurrences(p, t)
        if not (l <= occurrences <= r):
            return False
    return True

def main():
    s = input().strip()
    n = int(input())
    rules = []
    for _ in range(n):
        parts = input().split()
        p = parts[0]
        l = int(parts[1])
        r = int(parts[2])
        rules.append((p, l, r))

    # Generate all distinct substrings of s
    substrings = set()
    for i in range(len(s)):
        for j in range(i, len(s)):
            substrings.add(s[i:j+1])

    # Count good substrings
    good_count = 0
    for t in substrings:
        if is_good(t, rules):
            good_count += 1

    print(good_count)

if __name__ == "__main__":
    main()
