# Track all possible positions at each step
positions = {(0, 0)}

for i in range(n - 1, -1, -1):
    movement = movements[i]
    new_positions = set()

    if movement == "UL":
        # Could have moved from (x, y) to (x, y+1) or (x-1, y)
        for x, y in positions:
            new_positions.add((x, y + 1))
            new_positions.add((x - 1, y))
    elif movement == "UR":
        # Could have moved from (x, y) to (x, y+1) or (x+1, y)
        for x, y in positions:
            new_positions.add((x, y + 1))
            new_positions.add((x + 1, y))
    elif movement == "DL":
        # Could have moved from (x, y) to (x, y-1) or (x-1, y)
        for x, y in positions:
            new_positions.add((x, y - 1))
            new_positions.add((x - 1, y))
    elif movement == "DR":
        # Could have moved from (x, y) to (x, y-1) or (x+1, y)
        for x, y in positions:
            new_positions.add((x, y - 1))
            new_positions.add((x + 1, y))
    elif movement == "ULDR":
        # Could have moved from (x, y) to any of the four directions
        for x, y in positions:
            new_positions.add((x, y + 1))
            new_positions.add((x - 1, y))
            new_positions.add((x, y - 1))
            new_positions.add((x + 1, y))

    positions = new_positions

print(len(positions))
