import sys

def is_good(sub):
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    v = sum(1 for c in sub if c in vowels)
    return v <= 2 * len(sub) - v

def solve(s):
    n = len(s)
    max_len = 0
    count = 0

    # Check all substrings
    for start in range(n):
        v_count = 0
        for end in range(start, n):
            if s[end] in {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}:
                v_count += 1

            if v_count <= 2 * (end - start + 1) - v_count:
                length = end - start + 1
                if length > max_len:
                    max_len = length
                    count = 1
                elif length == max_len:
                    count += 1

    if max_len == 0:
        return "No solution"
    else:
        return f"{max_len} {count}"

if __name__ == "__main__":
    s = sys.stdin.read().strip()
    result = solve(s)
    print(result)
"}

