            result += d[i - len(a)]
        else:
            result += '0'

    # Handle decimal point placement
    decimal_pos_in_result = len(a) + b
    if decimal_pos_in_result < len(result):
        int_part = result[:decimal_pos_in_result]
        dec_part = result[decimal_pos_in_result:]
        result = f"{int_part}.{dec_part}"
    elif decimal_pos_in_result == len(result):
        result = result.rstrip('0')
        if len(result) > 0:
            int_part = result
            dec_part = ''
            result = f"{int_part}"
        else:
            result = '0'
    else:
        # decimal_pos_in_result > len(result)
        result = '0' + '.' + '0' * (decimal_pos_in_result - len(result))

    # Remove trailing zeros
    if '.' in result:
        int_part, dec_part = result.split('.')
        dec_part = dec_part.rstrip('0')
        if len(dec_part) == 0:
            print(int_part)
        else:
            print(f"{int_part}.{dec_part}")
    else:
        print(result)

