n, m = map(int, input().split())

# Count non-edges for each vertex
count_non_edges = [0] * (n + 1)

# Also store which vertices are non-adjacent to which
non_adjacent = [[] for _ in range(n + 1)]

for _ in range(m):
    x, y = map(int, input().split())
    count_non_edges[x] += 1
    count_non_edges[y] += 1
    non_adjacent[x].append(y)
    non_adjacent[y].append(x)

# Union-Find implementation
class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.size = [1] * size
        self.rank = [0] * size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False  # already in same set
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        elif self.rank[x_root] > self.rank[y_root]:
            self.parent[y_root] = x_root
        else:
            self.parent[y_root] = x_root
            self.rank[x_root] += 1
        self.size[x_root] += self.size[y_root]
        return True

# Find vertices that are NOT isolated (have at least one connection)
non_isolated = [False] * (n + 1)
for i in range(1, n + 1):
    if count_non_edges[i] < n - 1:
        non_isolated[i] = True

# Union of all non-isolated vertices that are adjacent
uf = UnionFind(n + 1)
for i in range(1, n + 1):
    if non_isolated[i]:
        for j in non_adjacent[i]:
            if non_isolated[j]:
                uf.union(i, j)

# Find connected components of non-isolated vertices
components = set()
for i in range(1, n + 1):
    if non_isolated[i]:
        components.add(uf.find(i))

# Count component sizes
component_sizes = []
for i in range(1, n + 1):
    if non_isolated[i]:
        component_sizes.append(uf.size[uf.find(i)])

# Add isolated vertices as size 1 components
component_sizes.extend([1] * sum(1 for i in range(1, n + 1) if count_non_edges[i] == n - 1))

# Sort
component_sizes.sort()

# Output
print(len(component_sizes))
print(' '.join(map(str, component_sizes)))
"}

