grid = []
for _ in range(H):
    grid.append(input().strip())

# dp[i][j] = maximum berries collected from (0,0) to (i,j)
dp = [[0] * W for _ in range(H)]

dp[0][0] = 1 if grid[0][0] == '*' else 0

for i in range(H):
    for j in range(W):
        if i == 0 and j == 0:
            continue

        # Can come from above or from the left
        max_berry = 0
        if i > 0:
            max_berry = max(max_berry, dp[i-1][j])
        if j > 0:
            max_berry = max(max_berry, dp[i][j-1])

        # Add berry at current position if there is one
        dp[i][j] = max_berry + (1 if grid[i][j] == '*' else 0)

print(dp[H-1][W-1])
