def min_resistors(a, b):
    """Find minimum number of resistors to create resistance a/b"""

    # Base case: if a == 1, need b resistors in parallel
    if a == 1:
        return b

    # Try both possibilities
    # 1. Series: a/b = Re + 1 => Re = (a-b)/b
    # 2. Parallel: a/b = Re/(Re+1) => Re = a/(b-a)

    # Use recursion with memoization
    memo = {}

    def dfs(a, b):
        if (a, b) in memo:
            return memo[(a, b)]

        # Base case
        if a == 1:
            memo[(a, b)] = b
            return b

        # Try series connection
        if a > b:
            series = dfs(a - b, b) + 1
        else:
            series = float('inf')  # Can't do series if a <= b

        # Try parallel connection
        if b > a:
            parallel = dfs(a, b - a) + 1
        else:
            parallel = float('inf')  # Can't do parallel if b <= a

        result = min(series, parallel)
        memo[(a, b)] = result
        return result

    return dfs(a, b)

# Read input
a, b = map(int, input().split())

# Solve and print
print(min_resistors(a, b))
