import sys
from collections import defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = data[2:2+n]

    # For each row, find the best pattern
    best_cost = float('inf')
    best_grid = []

    for row_idx in range(n):
        row = grid[row_idx]
        best_cost_row = float('inf')
        best_pattern = None

        # Try all combinations of keeping 1 or 2 colors
        # Count frequency of each color
        color_counts = defaultdict(int)
        for ch in row:
            color_counts[ch] += 1

        # Try keeping 1 color (only possible if adjacent cells are different)
        # Actually, we can't keep all same color - we need to alternate
        # So we need to introduce at least one other color

