    # State: (position, prev_val, humps, valleys, trend, is_peak, is_valley)
    # trend: 0 - no trend yet, 1 - increasing, 2 - decreasing
    # is_peak: True if we're at a peak (local maximum), False otherwise
    # is_valley: True if we're at a valley (local minimum), False otherwise

