def count_sequences(n, t):
    """Count the number of valid sequences of length n with exactly t humps and t-1 valleys."""

    # State: (position, prev_val, curr_val, humps, valleys)

    # Initialize: at position 2 with a starting pair of values
    # We start at position 2 to have prev_val and curr_val
    dp = {} 
    for prev_val in range(1, 5):
        for curr_val in range(1, 5):
            if prev_val != curr_val:
                state = (2, prev_val, curr_val, 0, 0)
                dp[state] = 1

    for pos in range(2, n):
        new_dp = {}
        for state, count in dp.items():
            position, prev_val, curr_val, humps, valleys = state

            # Try all possible next values
            for next_val in range(1, 5):
                if curr_val == next_val:
                    continue  # No horizontal segment

                # Check if we've reached a peak or valley at position pos
                # For position j (2 ≤ j ≤ n-1), we look at j-1, j, j+1
                # So when we're at position j, we look at j-1 and j
                # When we're at position j+1, we've seen all three
                if prev_val < curr_val and curr_val > next_val:
                    # We've reached a peak (local maximum)
                    if humps < t:
                        new_humps = humps + 1
                        new_valleys = valleys
                    else:
                        continue
                elif prev_val > curr_val and curr_val < next_val:
                    # We've reached a valley (local minimum)
                    if valleys < t - 1:
                        new_valleys = valleys + 1
                        new_humps = humps
                    else:
                        continue
                else:
                    new_humps = humps
                    new_valleys = valleys

                # Update state for next position
                new_state = (pos + 1, curr_val, next_val, new_humps, new_valleys)
                new_dp[new_state] = new_dp.get(new_state, 0) + count

        dp = new_dp

    # Count all valid sequences at position n
    total = 0
    for state, count in dp.items():
        _, _, _, humps, valleys = state
        if humps == t and valleys == t - 1:
            total += count

    return total

# Read input
n, t = map(int, input().split())

# Solve and print
print(count_sequences(n, t))

