def get_rotations(piece):
    """Get all rotations of a piece (including original)."""
    X, Y = len(piece), len(piece[0])
    rotations = []

    # 0° rotation (original)
    rotations.append([row[:] for row in piece])

    # 90° rotation: (Y, X) size, rotated[y][x] = original[0 + y][X - 1 - x]
    if Y != X:
        rotated = [[0] * X for _ in range(Y)]
        for y in range(Y):
            for x in range(X):
                rotated[y][x] = piece[0 + y][X - 1 - x]
        rotations.append(rotated)

    # 180° rotation: (X, Y) size, rotated[y][x] = original[X - 1 - y][Y - 1 - x]
    rotated = [[0] * Y for _ in range(X)]
    for y in range(X):
        for x in range(Y):
            rotated[y][x] = piece[X - 1 - y][Y - 1 - x]
    rotations.append(rotated)

    # 270° rotation: (Y, X) size, rotated[y][x] = original[Y - 1 - y][X - 1 - x]
    if Y != X:
        rotated = [[0] * X for _ in range(Y)]
        for y in range(Y):
            for x in range(X):
                rotated[y][x] = piece[Y - 1 - y][X - 1 - x]
        rotations.append(rotated)

    return rotations

def is_valid(A, B, picture, X, Y):
    """Check if cutting into X×Y pieces is valid."""
    if A % X != 0 or B % Y != 0:
        return False

    # Cut into pieces
    pieces = []
    for i in range(0, A, X):
        for j in range(0, B, Y):
            # Extract piece at (i, j)
            piece = []
            for y in range(X):
                row = []
                for x in range(Y):
                    row.append(picture[i + y][j + x])
                piece.append(row)
            pieces.append(piece)

    # Check for duplicates
    seen = set()
    for piece in pieces:
        # Get all rotations
        rotations = get_rotations(piece)

        # Check if any rotation is already seen
        duplicate = False
        for rot in rotations:
            # Convert to tuple of tuples for hashability
            rot_tuple = tuple(tuple(row) for row in rot)
            if rot_tuple in seen:
                duplicate = True
                break
        if duplicate:
            return False

        # Add all rotations to seen
        for rot in rotations:
            rot_tuple = tuple(tuple(row) for row in rot)
            seen.add(rot_tuple)

    return True

