def solve():
    MOD = 1000000007
    n, m, k = map(int, input().split())

    # Create transition matrix (m x m)
    trans = [[0] * m for _ in range(m)]

    # All transitions are allowed initially
    for i in range(m):
        for j in range(m):
            trans[i][j] = 1

    # Read forbidden pairs
    for _ in range(k):
        pair = input().strip()
        # Convert to 0-indexed indices
        i = ord(pair[0]) - ord('a') if 'a' <= pair[0] <= 'z' else ord(pair[0]) - ord('A') + 26
        j = ord(pair[1]) - ord('a') if 'a' <= pair[1] <= 'z' else ord(pair[1]) - ord('A') + 26

        if i < m and j < m:
            trans[i][j] = 0

    if n == 1:
        print(m % MOD)
        return

    # Instead of matrix exponentiation, let's compute the answer directly
    # This should work for small n

    # Initial state: each nucleotide is valid at position 1
    dp = [1] * m

    for _ in range(1, n):
        new_dp = [0] * m
        for i in range(m):
            for j in range(m):
                if trans[i][j] == 1:
                    new_dp[i] = (new_dp[i] + dp[j]) % MOD
        dp = new_dp

    print(sum(dp) % MOD)

solve()
