def solve():
    n, m, k, s = map(int, input().split())

    # Map from note value to list of (string, fret) positions
    note_positions = [[] for _ in range(k + 1)]
    for i in range(n):
        row = list(map(int, input().split()))
        for j in range(m):
            note = row[j]
            note_positions[note].append((i + 1, j + 1))  # 1-indexed

    # Song notes
    song = list(map(int, input().split()))

    # dp[i][s][f] = max complexity up to note i ending at position (s, f)
    # Since k <= 9 and n, m <= 2000, we can afford O(nm) storage per note

    # For each note, we just need to track which positions produce it
    prev_positions = []
    for note in song:
        prev_positions.append(note_positions[note])

    # dp: max complexity up to note i ending at position (s, f)
    # We'll store complexity for each position
    complexity = [-1] * (n * m + 1)

    # Initialize first note
    for i, (s_pos, f_pos) in enumerate(prev_positions[0]):
        idx = i
        complexity[idx] = 0

    # DP
    for i in range(1, s):
        curr_positions = prev_positions[i]
        curr_idx_map = {}
        for j, (s_pos, f_pos) in enumerate(curr_positions):
            curr_idx_map[(s_pos, f_pos)] = j
            complexity[j] = -1

        prev_positions_ref = prev_positions[i - 1]
        prev_idx_map = {}
        for j, (s_pos, f_pos) in enumerate(prev_positions_ref):
            prev_idx_map[(s_pos, f_pos)] = j

        for curr_s, curr_f in curr_positions:
            idx_curr = curr_idx_map[(curr_s, curr_f)]
