import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        r = int(next(it))
        c = int(next(it))
        grid = []
        for _ in range(r):
            row = next(it)
            grid.append(list(row))

        # Find all A positions
        a_positions = []
        for i in range(r):
            for j in range(c):
                if grid[i][j] == 'A':
                    a_positions.append((i, j))

        # BFS from all A positions
        visited = [[False]*c for _ in range(r)]

        # Queue for BFS (coordinates)
        q = deque()

        # Initialize queue with A positions
        for i, j in a_positions:
            grid[i][j] = 'P'  # Mark as visited
            q.append((i, j))

        operations = 0

        while q:
            operations += 1

            # Convert all P adjacent to current A/converted A
            new_q = deque()
            for _ in range(len(q)):
                i, j = q.popleft()

                # Check all 4 directions
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < r and 0 <= nj < c:
                        if not visited[ni][nj] and grid[ni][nj] == 'P':
                            visited[ni][nj] = True
                            grid[ni][nj] = 'A'
                            new_q.append((ni, nj))

            q = new_q

        # Check if all cells are A
        for i in range(r):
            for j in range(c):
                if grid[i][j] == 'P':
                    out_lines.append("MORTAL")
                    break
            else:
                continue
            break
        else:
            out_lines.append(str(operations))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
