import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        r = int(next(it))
        c = int(next(it))
        grid = []
        for _ in range(r):
            row = next(it)
            grid.append(list(row))

        # Multi-source BFS to find minimum operations
        visited = [[False]*c for _ in range(r)]

        # Queue for BFS (coordinates)
        q = deque()

        # Initialize queue with A positions
        for i in range(r):
            for j in range(c):
                if grid[i][j] == 'A':
                    visited[i][j] = True
                    q.append((i, j))

        # BFS to find distance from nearest A
        dist = [[-1]*c for _ in range(r)]
        while q:
            i, j = q.popleft()
            dist[i][j] = 0

            # Check all 4 directions
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < r and 0 <= nj < c and not visited[ni][nj]:
                    visited[ni][nj] = True
                    dist[ni][nj] = dist[i][j] + 1
                    q.append((ni, nj))

        # Check if all cells are A (visited)
        for i in range(r):
            for j in range(c):
                if not visited[i][j]:
                    out_lines.append("MORTAL")
                    break
            else:
                continue
            break
        else:
            # Minimum number of operations is max distance
            max_dist = max(max(row) for row in dist)
            out_lines.append(str(max_dist))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
