def square_free(n):
    """Compute the square-free part of n"""
    result = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            n //= i
            if n % i == 0:
                # i^2 divides n, so we keep it out
                pass
            else:
                # i divides n but i^2 does not, so we keep one copy
