def square_free_part(x):
    """Return square-free part of x"""
    if x == 0:
        return 0
    res = 1
    i = 2
    while i * i <= x:
        if x % i == 0:
            x //= i
            if x % i == 0:
                res *= i
            else:
                res *= i
        i += 1
    if x > 1:
        res *= x
    return res

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        q = int(next(it))
        queries = [int(next(it)) for _ in range(q)]

        # Compute square-free parts
        sq_free = [square_free_part(x) for x in a]

        # Count frequency
        from collections import defaultdict
        count = defaultdict(int)
        for sf in sq_free:
            count[sf] += 1

        # Precompute
        odd_squares = []
        even_squares = []
        for sf, c in count.items():
            if c % 2 == 1:
                odd_squares.append(c)
            else:
                even_squares.append(c)

        # For w=0: max odd/even
        max_odd = max(odd_squares) if odd_squares else 0
        max_even = max(even_squares) if even_squares else 0

        # For w>=1: max after 1 second
        max_after_1 = 0
        if odd_squares:
            max_after_1 = max(odd_squares)
        if even_squares:
            max_after_1 = max(max_after_1, sum(even_squares))

        # Process queries
        for w in queries:
            if w == 0:
                out_lines.append(str(max_odd if odd_squares else 0))
            elif w == 1:
                out_lines.append(str(max_after_1))
            else:
                if odd_squares:
                    out_lines.append(str(max_after_1))
                else:
                    out_lines.append(str(1))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

