class State:
    def __init__(self):
        self.next = dict()
        self.link = -1
        self.len = 0
        self.cnt = 0

class SuffixAutomaton:
    def __init__(self):
        self.size = 1
        self.last = 0
        self.states = [State()]

    def sa_extend(self, c):
        p = self.last
        curr = self.size
        self.size += 1
        self.states.append(State())
        self.states[curr].len = self.states[p].len + 1
        self.states[curr].cnt = 1

        while p >= 0 and c not in self.states[p].next:
            self.states[p].next[c] = curr
            p = self.states[p].link

        if p == -1:
            self.states[curr].link = 0
        else:
            q = self.states[p].next[c]
            if self.states[p].len + 1 == self.states[q].len:
                self.states[curr].link = q
            else:
                clone = self.size
                self.size += 1
                self.states.append(State())
                self.states[clone].len = self.states[p].len + 1
                self.states[clone].next = self.states[q].next.copy()
                self.states[clone].link = self.states[q].link
                self.states[clone].cnt = 0

                while p >= 0 and self.states[p].next[c] == q:
                    self.states[p].next[c] = clone
                    p = self.states[p].link

                self.states[q].link = clone
                self.states[curr].link = clone

        self.last = curr

    def count(self, t):
        # Count occurrences of substring t in the automaton
        state = self.last
        for ch in t:
            if ch not in self.states[state].next:
                return 0
            state = self.states[state].next[ch]
        return self.states[state].cnt


def main():
    s = input().strip()
    n = int(input())
    rules = []
    for _ in range(n):
        parts = input().split()
        p = parts[0]
        l = int(parts[1])
        r = int(parts[2])
        rules.append((p, l, r))

    # Preprocess rules
    rule_info = {}
    for p, l, r in rules:
        sa = SuffixAutomaton()
        for ch in p:
            sa.sa_extend(ch)
        rule_info[(p, l, r)] = sa

    # Generate all substrings of s
    good_substrings = set()
    for i in range(len(s)):
        for j in range(i, len(s)):
            t = s[i:j+1]
            # Check if t complies with all rules
            valid = True
            for p, l, r in rules:
                sa = rule_info[(p, l, r)]
                count = sa.count(t)
                if count < l or count > r:
                    valid = False
                    break

            if valid:
                good_substrings.add(t)

    print(len(good_substrings))

if __name__ == "__main__":
    main()
