{"code": "
def is_balanced(s):
    """Check if s is balanced"""
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
    return balance == 0

def is_correct_sequence(s):
    """Check if s is a correct bracket sequence"""
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def count_correct_cyclical_shifts(s):
    """Count how many cyclical shifts are correct"""
    n = len(s)
    if not is_balanced(s):
        return 0

    # For a balanced string, check all rotations
    correct_count = 0
    for k in range(n):
        # Cyclical shift by k
        shifted = s[k:] + s[:k]
        if is_correct_sequence(shifted):
            correct_count += 1
    return correct_count

def solve() -> None:
    n = int(input())
    s = input()

    # Check if we can balance the string
    left_parentheses = s.count('(')
    right_parentheses = n - left_parentheses

    if n % 2 != 0 or abs(left_parentheses - right_parentheses) > 1:
        # Can't balance, answer is 0
        print(0)
        print(1, 1)
        return

    # Original string
    original_count = count_correct_cyclical_shifts(s)

    # Try all possible swaps that balance the string
    max_count = original_count
    best_l, best_r = 1, 1

    # For each '(' at i, try swapping with each ')' at j
    for i in range(n):
        if s[i] == '(':
            for j in range(n):
                if s[j] == ')':
                    # Swap i and j
                    s_list = list(s)
                    s_list[i], s_list[j] = s_list[j], s_list[i]
                    new_string = ''.join(s_list)

                    count = count_correct_cyclical_shifts(new_string)

                    if count > max_count:
                        max_count = count
                        best_l, best_r = i + 1, j + 1

                    # Restore
                    s_list[i], s_list[j] = s_list[j], s_list[i]


    print(max_count)
    print(best_l, best_r)

solve()
