def find_perfect_growth_sequence(n, a):
    """Find the longest perfect growth sequence in the given year-income data."""
    # dp[i] = (max_length, last_value)
    dp = [(0, 0)] * (n + 1)  # 1-indexed

    # dp[i] will store: (max_length, last_value) for the perfect sequence ending at year i
    for i in range(1, n + 1):
        val = a[i - 1]

        # If value is 1, we can start a sequence here
        if val == 1:
            dp[i] = (1, 1)

        # Otherwise, look for value-1 in previous years
        elif val > 1:
            max_len = 0
            best_j = 0

            # Look at all previous years
            for j in range(1, i):
                if dp[j][1] == val - 1 and dp[j][0] > max_len:
                    max_len = dp[j][0]
                    best_j = j

            if max_len > 0:
                dp[i] = (max_len + 1, val)

    # Find the maximum length sequence
    max_len = 0
    best_index = 0
    for i in range(1, n + 1):
        if dp[i][0] > max_len:
            max_len = dp[i][0]
            best_index = i

    # Reconstruct the sequence by going backward
    result = []
    if max_len > 0:
        current = best_index
        for _ in range(max_len):
            result.append(current)
            # Find the previous year in the sequence
            for j in range(current - 1, 0, -1):
                if dp[j][1] == dp[current][1] - 1 and dp[j][0] == dp[current][0] - 1:
                    current = j
                    break

    # Convert years to 2000 + year format
    years = [2000 + y for y in result]

    return max_len, years

