def find_min_rows(n, m, matrix):
    # Try all possible matrix b sizes (x) where x divides n
    for x in range(1, n + 1):
        if n % x != 0:
            continue

        # Check if matrix is valid for this x (number of rows in matrix b)
        valid = True
        for i in range(1, n + 1):
            # Row i should be equal to row (i % x) if i <= x, or row (i - x) if i > x
            if i <= x:
                expected_row_index = i - 1
            else:
                expected_row_index = (i - x - 1) % x

            # Check if row i matches the expected row
            if matrix[i - 1] != matrix[expected_row_index]:
                valid = False
                break

        if valid:
            return x
    return n

