def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    probs = list(map(float, data[1:1+n]))

    max_prob = 0.0

    # Consider all subsets
    for mask in range(1 << n):
        # Calculate the probability of exactly one success in this subset
        p_success = 0.0

        # Find which friends are in this subset
        for i in range(n):
            if (mask >> i) & 1:
                # Friend i is in the subset
                # Calculate product of (1 - p) for all friends in the subset except i
                product = 1.0
                for j in range(n):
                    if (mask >> j) & 1 and j != i:
