def count_distinct_sums(n):
    # The key insight: we can get any sum between n and 50n
    # but not all values are achievable

    # For small n, we can calculate using DP
    max_sum = 50 * n
    dp = [[0] * (max_sum + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(i, max_sum + 1):
            dp[i][j] = dp[i-1][j-1] + dp[i-1][j-5] + dp[i-1][j-10] + dp[i-1][j-50]

    distinct_sums = 0
    for j in range(n, max_sum + 1):
        if dp[n][j] > 0:
            distinct_sums += 1

    return distinct_sums

n = int(input())
print(count_distinct_sums(n))
