n, m = map(int, input().split())

# non_edges[x] = set of vertices x is NOT connected to
non_edges = [set() for _ in range(n + 1)]

for _ in range(m):
    x, y = map(int, input().split())
    non_edges[x].add(y)
    non_edges[y].add(x)

# Union-Find data structure
parent = list(range(n + 1))
size = [1] * (n + 1)

def find(u):
    while parent[u] != u:
        parent[u] = parent[parent[u]]
        u = parent[u]
    return u

def union(u, v):
    u_root = find(u)
    v_root = find(v)
    if u_root == v_root:
        return

    # Union by size
    if size[u_root] < size[v_root]:
        u_root, v_root = v_root, u_root

    parent[v_root] = u_root
    size[u_root] += size[v_root]

# For vertices with few non-edges, iterate through all vertices
# For vertices with many non-edges, iterate through their non-edges
threshold = int(n ** 0.5) + 1

for v in range(1, n + 1):
    if len(non_edges[v]) < threshold:
        # v has few non-edges, so it's connected to many vertices
        # Iterate through all vertices and check if there's an edge
        for u in range(1, n + 1):
            if u == v:
                continue
            if u not in non_edges[v]:
                union(v, u)
    else:
        # v has many non-edges, so it's not connected to many vertices
        # Iterate through its non-edges and merge
        for u in non_edges[v]:
            union(v, u)

# Count component sizes
component_sizes = {}
for v in range(1, n + 1):
    root = find(v)
    if root not in component_sizes:
        component_sizes[root] = size[root]

# Output
print(len(component_sizes))
for size in sorted(component_sizes.values()):
    print(size)
