import sys

def is_unimodal(a):
    n = len(a)
    if n == 1:
        return True
    state = 0  # 0: increasing, 1: flat, 2: decreasing
    for i in range(1, n):
        prev = a[i-1]
        curr = a[i]
        if state == 0:  # increasing
            if curr == prev:
                state = 1
            elif curr < prev:
                # directly decreasing without flat
                return False
        elif state == 1:  # flat
            if curr > prev:
                # increasing after flat
                return False
            elif curr < prev:
                state = 2
        elif state == 2:  # decreasing
            if curr >= prev:
                # cannot increase or stay equal after decreasing
                return False
    return True

