def longest_increasing_subarray(arr):
    """Find the longest strictly increasing contiguous subarray"""
    max_len = 1
    current_len = 1
    for i in range(1, len(arr)):
        if arr[i] > arr[i-1]:
            current_len += 1
            max_len = max(max_len, current_len)
        else:
            current_len = 1
    return max_len

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Find the longest increasing subarray in the original array
    max_len = longest_increasing_subarray(a)

    # For each element, consider removing it
    for i in range(n):
        # Find the longest increasing subarray ending at i-1
        inc_before = 1
        for j in range(i-1, 0, -1):
            if a[j] < a[j-1]:
                inc_before += 1
            else:
                break

        # Find the longest increasing subarray starting at i+1
        inc_after = 1
        for j in range(i+1, n):
            if a[j] > a[j-1]:
                inc_after += 1
            else:
                break

        # Combine if possible
        if i == 0:
            combined = inc_after
        elif i == n-1:
            combined = inc_before
        else:
            combined = inc_before + inc_after

        max_len = max(max_len, combined)

    print(max_len)

if __name__ == "__main__":
