n, m = map(int, input().split())
maze = []
start_pos = None
exit_pos = None

for i in range(n):
    row = list(input().strip())
    maze.append(row)
    for j in range(m):
        if row[j] == 'S':
            start_pos = (i, j)
        elif row[j] == 'E':
            exit_pos = (i, j)

s = input().strip()

# Directions: 0-up, 1-left, 2-right, 3-down
directions = {
    0: (-1, 0),  # up
    1: (0, -1),  # left
    2: (0, 1),   # right
    3: (1, 0)    # down
}

used_digits = set(s)
num_mappings = 0

# Try all permutations of assigning directions to digits
from itertools import permutations

for perm in permutations(directions.values()):
    # Create a mapping: digit -> direction
    mapping = {}
    for digit, direction in zip(used_digits, perm):
        mapping[digit] = direction

    # Simulate
    pos = start_pos
    reached_exit = False

    for ch in s:
        if reached_exit:
            break

        dir_vec = mapping[int(ch)]
        new_pos = (pos[0] + dir_vec[0], pos[1] + dir_vec[1])

        # Check if new position is valid
        if 0 <= new_pos[0] < n and 0 <= new_pos[1] < m:
            cell = maze[new_pos[0]][new_pos[1]]
            if cell == '#':
                # Crash
                break
            elif cell == 'E':
                # Reached exit
                reached_exit = True
                break
            else:
                # Move to new position
                pos = new_pos
        else:
            # Out of bounds
            break

    if reached_exit:
        num_mappings += 1

print(num_mappings)
